import { z } from "zod";

const UsuarioSchema = z.object({
  nome: z.string(),
  idade: z.number(),
});

type Usuario = z.infer<typeof UsuarioSchema>;

const res = UsuarioSchema.safeParse({ nome: "Ana", idade: 25 });
console.log(res.success);
